query:
query Diablo4NgfStaticDataQuery($skillsFilter: D4SkillsFilter, $aspectsFilter: D4AspectsFilter, $uniqueItemsFilter: D4UniqueItemsFilter, $runesFilter: D4RunesFilter, $gemsFilter: D4GemsFilter, $witchcraftPowersFilter: D4WitchcraftPowersFilter, $bossPowersFilter: D4BossPowersFilter, $paragonBoardFilter: D4ParagonBoardsFilter, $paragonGlyphFilter: D4ParagonGlyphsFilter, $paragonNodesFilter: D4ParagonNodesFilter, $classesFilter: D4ClassesFilter, $skillSectionsFilter: D4SkillSectionsFilter, $skillTreeConnectorsFilter: D4ConnectorsFilter, $buildSlotsFilter: D4BuildSlotsFilter, $statsFilter: D4StatsFilter, $statImplicitFilter: D4StatImplicitFilter, $statTemperingFilter: D4StatTemperingFilter, $transfiguredStatsFilter: D4TransfiguredStatsFilter, $mercenariesFilter: D4MercenariesFilter, $mercenarySkillsFilter: D4MercenarySkillsFilter, $reinforcementMercenaryOpportunitiesFilter: D4OpportunitiesFilter, $chaosPerksFilter: D4ChaosPerksFilter, $bloodiedAffixesFilter: D4BloodiedAffixesFilter, $divineGiftsFilter: D4DivineGiftsFilter, $elixirsFilter: D4ElixirsFilter, $soulShardsFilter: D4SoulShardsFilter, $charmsFilter: D4CharmsFilter, $sealsFilter: D4SealsFilter) {
  game: diablo4 {
    staticData: staticDataV2 {
      d4Skills(filter: $skillsFilter) {
        data {
          ...D4SkillTreeSkillFragment
        }
      }
      d4Aspects(filter: $aspectsFilter) {
        data {
          ...D4AspectFragment
        }
      }
      d4UniqueItems(filter: $uniqueItemsFilter) {
        data {
          ...D4UniqItemFragment
        }
      }
      d4Runes(filter: $runesFilter) {
        data {
          ...D4RuneFragment
        }
      }
      d4Gems(filter: $gemsFilter) {
        data {
          ...D4GemFragment
        }
      }
      d4WitchcraftPowers(filter: $witchcraftPowersFilter) {
        data {
          ...D4WitchcraftPowerFragment
        }
      }
      d4BossPowers(filter: $bossPowersFilter) {
        data {
          ...D4BossPowerFragment
        }
      }
      d4ParagonBoards(filter: $paragonBoardFilter) {
        data {
          ...D4ParagonBoardFragment
        }
      }
      d4ParagonGlyphs(filter: $paragonGlyphFilter) {
        data {
          ...D4ParagonBoardGlyphFragment
        }
      }
      d4ParagonNodes(filter: $paragonNodesFilter) {
        data {
          ...D4ParagonBoardNodeFragment
        }
      }
      d4Classes(filter: $classesFilter) {
        data {
          ...D4ClassFragment
        }
      }
      d4SkillSections(filter: $skillSectionsFilter) {
        data {
          ...D4SkillSectionFragment
        }
      }
      d4Connectors(filter: $skillTreeConnectorsFilter) {
        data {
          ...D4SkillTreeConnectorFragment
        }
      }
      d4BuildSlots(filter: $buildSlotsFilter) {
        data {
          ...D4BuildSlotFragment
        }
      }
      d4Stats(filter: $statsFilter) {
        data {
          ...D4StatFragment
        }
      }
      d4StatImplicit(filter: $statImplicitFilter) {
        data {
          ...D4StatImplicitFragment
        }
      }
      d4StatTempering(filter: $statTemperingFilter) {
        data {
          ...D4StatTemperingFragment
        }
      }
      d4TransfiguredStats(filter: $transfiguredStatsFilter) {
        data {
          ...D4TransfiguredStatFragment
        }
      }
      d4Mercenaries(filter: $mercenariesFilter) {
        data {
          ...D4MercenaryFragment
        }
      }
      d4MercenarySkills(filter: $mercenarySkillsFilter) {
        data {
          ...D4MercenarySkillFragment
        }
      }
      reinforcementMercenaryOpportunities: d4Opportunities(
        filter: $reinforcementMercenaryOpportunitiesFilter
      ) {
        data {
          ...D4MercenaryOpportunityFragment
        }
      }
      d4ChaosPerks(filter: $chaosPerksFilter) {
        data {
          ...D4ChaosPerkFragment
        }
      }
      d4BloodiedAffixes(filter: $bloodiedAffixesFilter) {
        data {
          ...D4BloodiedAffixFragment
        }
      }
      d4DivineGifts(filter: $divineGiftsFilter) {
        data {
          ...D4DivineGiftsFragment
        }
      }
      d4Elixirs(filter: $elixirsFilter) {
        data {
          ...D4ElixirsAndIncensesFragment
        }
      }
      d4SoulShards(filter: $soulShardsFilter) {
        data {
          ...D4SoulShardFragment
        }
      }
      d4Charms(filter: $charmsFilter) {
        data {
          ...D4CharmFragment
        }
      }
      d4Seals(filter: $sealsFilter) {
        data {
          ...D4SealFragment
        }
      }
      meta: d4Skills {
        version
      }
    }
  }
}

fragment D4SkillTreeSkillFragment on D4Skill {
  __typename
  id
  slug
  classSlug
  class {
    name
  }
  name
  description
  enchantment
  maxRank
  requiredRank
  iconUrl
  deprecated
  weaponArsenalSlots {
    id
    name
    iconUrl
  }
  x
  y
  section {
    id
    name
  }
  disables {
    id
    type {
      id
      name
    }
  }
  dependsOnSlugs: dependsOnV2Slugs
  type: typeV2 {
    id
    slug
    name
  }
  tags {
    name
  }
  resources {
    value
    name
  }
  substitutions {
    key
    values
  }
}

fragment D4AspectFragment on D4Aspect {
  __typename
  slug
  id
  name
  iconUrl
  description
  type {
    id
