  description
  deprecated
  iconUrl
  classes {
    id
    name
  }
  nodes {
    id
    name
    x
    y
    iconUrlNormal
    iconUrlActive
    effects
    requiredStats {
      value
      step
      type {
        name
      }
    }
    bonusAmount
    requires
    type {
      id
      name
    }
    nodeStats {
      value
      type {
        name
      }
    }
  }
}

fragment D4ParagonBoardGlyphFragment on D4ParagonGlyph {
  __typename
  id
  slug
  name
  iconUrl
  deprecated
  level: maxLevel
  radius: maxRadius
  affectedType {
    id
  }
  scaling
  rarity {
    id
    name
  }
  bonus
  additionalBonus
  value
  legendaryValue
  legendaryBonus
  requirementsStats {
    value
    type {
      id
      name
    }
  }
  radiusDistribution {
    radius
    level
  }
  class {
    id
    name
  }
